pub fn verify_data_column_sidecar<P: Preset>(data_column_sidecar: &DataColumnSidecar<P>) -> bool {
    let DataColumnSidecar {
        index,
        column,
        kzg_commitments,
        kzg_proofs,
        ..
    } = data_column_sidecar;

    // The sidecar index must be within the valid range
    if *index >= P::NumberOfColumns::U64 {
        return false;
    }

    // A sidecar for zero blobs is invalid
    if kzg_commitments.is_empty() {
        return false;
    }

    // The column length must be equal to the number of commitments/proofs
    if column.len() != kzg_commitments.len() || column.len() != kzg_proofs.len() {
        return false;
    }

    true
}

/// Verify if the KZG proofs are correct.
pub fn verify_kzg_proofs<P: Preset>(
    data_column_sidecar: &DataColumnSidecar<P>,
    backend: KzgBackend,
    metrics: Option<&Arc<Metrics>>,
) -> Result<bool> {
    let _timer = metrics.as_ref().map(|metrics| {
        metrics
            .data_column_sidecar_kzg_verification_batch
            .start_timer()
    });

    let DataColumnSidecar {
        index,
        column,
        kzg_commitments,
        kzg_proofs,
        ..
    } = data_column_sidecar;

    let cell_indices: Vec<u64> = vec![*index; column.len()];

    verify_cell_kzg_proof_batch::<P>(kzg_commitments, cell_indices, column, kzg_proofs, backend)
}

pub fn verify_sidecar_inclusion_proof<P: Preset>(
    data_column_sidecar: &DataColumnSidecar<P>,
    metrics: Option<&Arc<Metrics>>,
) -> bool {
    let _timer = metrics.as_ref().map(|metrics| {
        metrics
            .data_column_sidecar_inclusion_proof_verification
            .start_timer()
    });

    let DataColumnSidecar {
        kzg_commitments,
        signed_block_header,
        kzg_commitments_inclusion_proof,
        ..
    } = data_column_sidecar;

    // Fields in BeaconBlockBody before blob KZG commitments
    let index_at_commitment_depth = 11;

    // is_valid_blob_sidecar_inclusion_proof
    is_valid_merkle_branch(
        kzg_commitments.hash_tree_root(),
        *kzg_commitments_inclusion_proof,
        index_at_commitment_depth,
        signed_block_header.message.body_root,
    )
}

pub fn recover_matrix<P: Preset>(
    partial_matrix: &[MatrixEntry<P>],
    backend: KzgBackend,
) -> Result<Vec<MatrixEntry<P>>> {
    let mut partial_matrix_map = BTreeMap::new();
    for matrix in partial_matrix {
        partial_matrix_map
            .entry(matrix.row_index)
            .or_insert(Vec::new())
            .push(matrix);
    }

    partial_matrix_map
        .into_par_iter()
        .map(|(_, entries)| {
            let (cell_indices, cells): (Vec<_>, Vec<_>) =
                entries.iter().map(|e| (e.column_index, &e.cell)).unzip();

            recover_cells_and_kzg_proofs::<P>(cell_indices, cells, backend)

pub fn is_valid_merkle_branch(
    leaf: H256,
    branch: impl IntoIterator<Item = H256>,
    index: u64,
    root: H256,
) -> bool {
    let mut hash = leaf;

    for (height, node) in branch.into_iter().enumerate() {
        if index.get_bit(height) {
            hash = hashing::hash_256_256(node, hash);
        } else {
            hash = hashing::hash_256_256(hash, node);
        }
    }

    hash == root
}

/// [`verify_blob_sidecar_inclusion_proof`](https://github.com/ethereum/consensus-specs/blob/v1.4.0-beta.5/specs/deneb/p2p-interface.md#verify_blob_sidecar_inclusion_proof)
///
/// Renamed to match [`is_valid_merkle_branch`].
#[must_use]
pub fn is_valid_blob_sidecar_inclusion_proof<P: Preset>(blob_sidecar: &BlobSidecar<P>) -> bool {
    // `consensus-specs` calls this `gindex`, but that is another misleading name.
    // This is NOT a generalized index.
    let index_at_commitment_depth = index_at_commitment_depth::<P>(blob_sidecar.index);

    is_valid_merkle_branch(
        blob_sidecar.kzg_commitment.hash_tree_root(),
        blob_sidecar.kzg_commitment_inclusion_proof,
        index_at_commitment_depth,
        blob_sidecar.signed_block_header.message.body_root,
    )
}

#[must_use]
pub fn is_valid_data_column_sidecar_inclusion_proof<P: Preset>(
    data_column_sidecar: &DataColumnSidecar<P>,
) -> bool {
    // Fields in BeaconBlockBody before blob KZG commitments
    let index_at_commitment_depth = 11;

    is_valid_merkle_branch(
        data_column_sidecar.kzg_commitments.hash_tree_root(),
        data_column_sidecar.kzg_commitments_inclusion_proof,
        index_at_commitment_depth,
        data_column_sidecar.signed_block_header.message.body_root,
    )
}

